	return i.Next.GetWorkflowResult(ctx, in)
}

func (i *workflowClientReadInterceptor) GetWorkflowHistory(ctx context.Context, in *ClientGetWorkflowHistoryInput) *ClientGetWorkflowHistoryOutput {
