	"github.com/nexus-rpc/sdk-go/nexus"
	"go.temporal.io/sdk/workflow"
)

type MyInput struct{}
type MyOutput struct{}

var myOperationRef = nexus.NewOperationReference[MyInput, MyOutput]("my-operation")

var myOperation = nexus.NewSyncOperation("my-operation", func(ctx context.Context, input MyInput, options nexus.StartOperationOptions) (MyOutput, error) {
	return MyOutput{}, nil
})

func ExampleNexusClient() {
	myWorkflow := func(ctx workflow.Context) (MyOutput, error) {
		client := workflow.NewNexusClient("my-endpoint", "my-service")
		// Execute an operation using an operation name.
		fut := client.ExecuteOperation(ctx, "my-operation", MyInput{}, workflow.NexusOperationOptions{
			ScheduleToCloseTimeout: time.Hour,
		})
		// Or using an OperationReference.
		fut = client.ExecuteOperation(ctx, myOperationRef, MyInput{}, workflow.NexusOperationOptions{
			ScheduleToCloseTimeout: time.Hour,
		})
		// Or using a defined operation (which is also an OperationReference).
		fut = client.ExecuteOperation(ctx, myOperation, MyInput{}, workflow.NexusOperationOptions{
			ScheduleToCloseTimeout: time.Hour,
		})

		var exec workflow.NexusOperationExecution
		// Optionally wait for the operation to be started.
		_ = fut.GetNexusOperationExecution().Get(ctx, &exec)
		// OperationToken will be empty if the operation completed synchronously.
		workflow.GetLogger(ctx).Info("operation started", "token", exec.OperationToken)

		// Get the result of the operation.
		var output MyOutput
		return output, fut.Get(ctx, &output)
	}

	_ = myWorkflow
}

package temporal

// This file somewhat mirrors the internal SearchAttributes implementation. The purpose of this is to
// test SearchAttributes.Copy()'s map iteration being ignored with `//workflowcheck:ignore`

type (
	SearchAttributeKey interface{}

	// SearchAttributes represents a collection of typed search attributes
	SearchAttributes struct {
		untypedValue map[SearchAttributeKey]interface{}
	}

	// SearchAttributeUpdate represents a change to SearchAttributes
	SearchAttributeUpdate func(*SearchAttributes)
)

// GetUntypedValues gets a copy of the collection with raw types.
func (sa SearchAttributes) GetUntypedValues() map[SearchAttributeKey]interface{} {
	untypedValueCopy := make(map[SearchAttributeKey]interface{}, len(sa.untypedValue))
	for key, value := range sa.untypedValue {
		// Filter out nil values
		if value == nil {
			continue
		}
		switch v := value.(type) {
		case []string:
			untypedValueCopy[key] = append([]string(nil), v...)
		default:
			untypedValueCopy[key] = v
		}
	}
	return untypedValueCopy
}

// Copy creates an update that copies existing values.
//
//workflowcheck:ignore
func (sa SearchAttributes) Copy() SearchAttributeUpdate {
	return func(s *SearchAttributes) {
		// GetUntypedValues returns a copy of the map without nil values
		// so the copy won't delete any existing values
		untypedValues := sa.GetUntypedValues()
		for key, value := range untypedValues {
			s.untypedValue[key] = value
		}
	}
}

