func updateParentWf(ctx Context) error {
	if err := SetUpdateHandler(ctx, "parent-handler", func(ctx Context, input any) error {
		return nil
	}, UpdateHandlerOptions{}); err != nil {
		return err
	}

	var childErr error
	if err := ExecuteChildWorkflow(WithChildWorkflowOptions(ctx, ChildWorkflowOptions{
		WorkflowID: "child-workflow",
	}), updateChildWf).Get(ctx, &childErr); err != nil {
		return err
	}
	return childErr
}

func updateChildWf(ctx Context) error {
	var done bool
	err := SetUpdateHandler(ctx, "child-handler", func(ctx Context, input any) error {
		done = true
		return nil
	}, UpdateHandlerOptions{})
	if err != nil {
		return err
	}

	return Await(ctx, func() bool {
		return done
	})
}

